package com.apiautomation.clients;public class UserApiClient extends ApiClient {public UserApiClient(String b){super(b);}public io.restassured.response.Response getUser(long id,String t){return get("/api/users/"+id,t);}public io.restassured.response.Response updateUser(long id,Object body,String t){return put("/api/users/"+id,body,t);}public io.restassured.response.Response deleteUser(long id,String t){return delete("/api/users/"+id,t);} }
